{
  "implementation": "import heapq

def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']

    # build lookup
    node_info = {}
    children = {}
    all_ids = []
    for node in nodes:
        nid = node['id']
        node_info[nid] = {
            'parent': node['parent'],
            'depth': node['depth'],
            'removable': node['removable'],
            'utility': node['utility']
        }
        children.setdefault(nid, [])
        all_ids.append(nid)

    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children.setdefault(parent, []).append(node['id'])

    # initial queue: descending depth, stable id (ascending)
    heap = []
    for nid in all_ids:
        heapq.heappush(heap, (-node_info[nid]['depth'], nid))

    removed = set()
    visit_order = []

    while heap:
        _, nid = heapq.heappop(heap)
        if nid in removed:
            continue
        visit_order.append(nid)
        node = node_info[nid]
        # check leaf: all children are removed
        leaf = all(cid in removed for cid in children.get(nid, []))
        if leaf and node['removable'] and node['utility'] <= threshold:
            removed.add(nid)
            parent = node['parent']
            if parent is not None and parent not in removed:
                heapq.heappush(heap, (-node_info[parent]['depth'], parent))

    retained = [nid for nid in all_ids if nid not in removed]
    return {
        'retained_node_ids': retained,
        'visit_order': visit_order
    }"
}
